(() => {
  const FIELDS = ["grossMonthlyIncome", "monthlyDebt", "newPayment", "creditScore"];
  const DTI_LIMIT_PCT = 43;
  const MIN_SCORE = 640;
  function validate(input) {
    if (input === null || typeof input !== "object" || Array.isArray(input)) {
      throw new Error("input must be an object");
    }
    for (const key of Object.keys(input)) {
      if (!FIELDS.includes(key)) throw new Error("unknown field: " + key);
    }
    for (const f of FIELDS) {
      if (!(f in input) || input[f] === void 0 || input[f] === null) {
        throw new Error("missing field: " + f);
      }
      const v = input[f];
      if (typeof v !== "number" || !Number.isFinite(v)) {
        throw new Error("field must be a finite number: " + f);
      }
      if (v < 0) throw new Error("field must not be negative: " + f);
    }
    if (input.grossMonthlyIncome === 0) {
      throw new Error("grossMonthlyIncome must be greater than zero");
    }
  }
  function failedDtiPercentText(total, income) {
    let tenths = Math.floor(total * 1e3 / income);
    if (tenths * income < total * 1e3) tenths += 1;
    if (tenths <= DTI_LIMIT_PCT * 10) tenths = DTI_LIMIT_PCT * 10 + 1;
    const whole = Math.floor(tenths / 10);
    const dec = tenths % 10;
    return dec === 0 ? String(whole) : whole + "." + dec;
  }
  function prequalify(input) {
    validate(input);
    const income = input.grossMonthlyIncome;
    const total = input.monthlyDebt + input.newPayment;
    const dti = total / income;
    const dtiPass = total * 100 <= income * DTI_LIMIT_PCT;
    const scorePass = input.creditScore >= MIN_SCORE;
    const reasons = [];
    if (!dtiPass) {
      reasons.push("Your monthly debt including this loan would be " + failedDtiPercentText(total, income) + "% of your gross income; the limit is " + DTI_LIMIT_PCT + "%");
    }
    if (!scorePass) {
      reasons.push("Your credit score is below the minimum of " + MIN_SCORE);
    }
    return { prequalified: dtiPass && scorePass, dti, reasons };
  }
  return { prequalify };
})()

