unitScript:
test("AC-1: DTI exactly 43% and score exactly 640 pre-qualifies with no reasons", () => {
  const r = code.prequalify({ grossMonthlyIncome: 5e3, monthlyDebt: 1500, newPayment: 650, creditScore: 640 });
  assert.equal(r.prequalified, true);
  assert.equal(r.dti, 0.43);
  assert.deepEqual(r.reasons, []);
});
test("AC-2: DTI of 44% declines with the DTI reason and the not-final notice", () => {
  const r = code.prequalify({ grossMonthlyIncome: 5e3, monthlyDebt: 1500, newPayment: 700, creditScore: 640 });
  assert.equal(r.prequalified, false);
  assert.equal(r.dti, 0.44);
  assert.deepEqual(r.reasons, [
    "Your monthly debt including this loan would be 44% of your gross income; the limit is 43%",
    "This is not a final decision"
  ]);
});
test("AC-3: score of 639 declines with the score reason and the not-final notice", () => {
  const r = code.prequalify({ grossMonthlyIncome: 5e3, monthlyDebt: 1500, newPayment: 650, creditScore: 639 });
  assert.equal(r.prequalified, false);
  assert.equal(r.dti, 0.43);
  assert.deepEqual(r.reasons, [
    "Your credit score is below the minimum of 640",
    "This is not a final decision"
  ]);
});
test("AC-4: both checks failing gives both reasons plus the not-final notice", () => {
  const r = code.prequalify({ grossMonthlyIncome: 5e3, monthlyDebt: 1500, newPayment: 700, creditScore: 639 });
  assert.equal(r.prequalified, false);
  assert.deepEqual(r.reasons, [
    "Your monthly debt including this loan would be 44% of your gross income; the limit is 43%",
    "Your credit score is below the minimum of 640",
    "This is not a final decision"
  ]);
});
test("DTI just above 43% declines and the stated percentage is not rounded down to 43", () => {
  const r = code.prequalify({ grossMonthlyIncome: 5e3, monthlyDebt: 1500, newPayment: 651, creditScore: 700 });
  assert.equal(r.prequalified, false);
  assert.match(r.reasons[0], /would be 43\.02% of your gross income; the limit is 43%/);
  assert.equal(r.reasons[r.reasons.length - 1], "This is not a final decision");
});
test("any field other than income, debt, new payment and score is rejected by name", () => {
  assert.throws(() => code.prequalify({ grossMonthlyIncome: 5e3, monthlyDebt: 1500, newPayment: 650, creditScore: 700, age: 30 }), /unknown field: age/);
});

